// Paperless-IDs (Instanz web-wikinger): Custom Fields und Select-Optionen
const CF = { rechnungsnummer: 1, zahlart: 2, firma: 3, brutto: 6, netto: 7, rechnungstyp: 8 };
const ZAHLART = { Rechnung: '9fyH21EOJWI8l7GF', Vorkasse: 'SlDzw9DHxVOmDnJD', Kreditkarte: 'hMSLnG9gG8elm97q',
                  Abo: 'L9U1lgDZsXvBnXqX', Lastschrift: 'vSSit6JyEqdBW4PJ', Paypal: 'jzEwRWEh7YPnA22y' };
const TYP = { Rechnung: '2b3JjQz0283yqzpB', Gutschrift: 'aS36nmVB2iRUY9U2', Stornorechnung: 'zTKbB4kUcRU95nKR' };
const TAG_GEPRUEFT = Number('18');   // ID des Tags "KI-geprüft" eintragen
if (!TAG_GEPRUEFT) throw new Error('Tag-ID "KI-geprüft" fehlt: KI_GEPRUEFT_TAG_ID hier und im Paperless-Abfrageknoten durch Zahl ersetzen');
const MIN_SICHERHEIT = 0.8;                          // darunter: nur Tag + Notiz, keine Feldänderung
const KORR = $('Paperless: Korrespondenten').first().json.results || [];
const norm = (t) => (t || '').toLowerCase().replace(/[^a-z0-9äöüß]+/g, ' ').trim();
const kompakt = (t) => norm(t).replace(/ /g, '');
const aehnlich = (a, b) => {                          // wie paperless/anreichern.py: aehnlich()
  const x = norm(a), y = norm(b);
  if (!x || !y) return false;
  if (x.includes(y) || y.includes(x)) return true;
  const w1 = x.split(' ')[0], w2 = y.split(' ')[0];
  return w1.length >= 6 && w2.length >= 6 && w1.slice(0, 6) === w2.slice(0, 6);
};

const out = [];
for (const [i, item] of $('Gemini-Prüfer').all().entries()) {
  const doc = $('Dokumente einzeln').all()[i].json;
  const ki = item.json.output || {};
  const felder = Object.fromEntries((doc.custom_fields || []).map(f => [f.field, f.value]));
  const vorher = { ...felder };
  const geld = (b) => (b == null ? null : `${(ki.waehrung || 'EUR').toUpperCase()}${Number(b).toFixed(2)}`);
  const soll = {
    [CF.rechnungsnummer]: ki.rechnungsnummer || null,
    [CF.firma]: ki.firma || null,
    [CF.brutto]: geld(ki.brutto),
    [CF.netto]: geld(ki.netto),
    [CF.zahlart]: ZAHLART[ki.zahlart] || null,
    [CF.rechnungstyp]: TYP[ki.rechnungstyp] || null,
  };
  const aenderungen = [];
  let korrespondent, korrespondentNeu = '';
  if ((ki.sicherheit ?? 0) >= MIN_SICHERHEIT && ki.firma) {   // OCR-Firma hat Vorrang vor bisherigem Korrespondenten
    const aktuell = KORR.find(k => k.id === doc.correspondent);
    if (!aktuell || !aehnlich(aktuell.name, ki.firma)) {
      const aehnliche = KORR.filter(k => aehnlich(k.name, ki.firma));
      const treffer = KORR.find(k => kompakt(k.name) === kompakt(ki.firma)) || (aehnliche.length === 1 ? aehnliche[0] : null);
      if (treffer) korrespondent = treffer.id; else korrespondentNeu = ki.firma;
      aenderungen.push(`Korrespondent: ${aktuell?.name ?? '–'} → ${treffer ? treffer.name : ki.firma + ' (neu)'}`);
    }
  }
  if ((ki.sicherheit ?? 0) >= MIN_SICHERHEIT) {
    for (const [fid, wert] of Object.entries(soll)) {
      if (wert != null && felder[fid] !== wert) {          // SevdeskID/Kundennummer werden nie angefasst
        aenderungen.push(`Feld ${fid}: ${felder[fid] ?? '–'} → ${wert}`);
        felder[fid] = wert;
      }
    }
  }
  const tags = [...new Set([...(doc.tags || []), TAG_GEPRUEFT])];
  out.push({ json: {
    id: doc.id,
    patch: { custom_fields: Object.entries(felder).map(([field, value]) => ({ field: Number(field), value })), tags,
             ...(korrespondent ? { correspondent: korrespondent } : {}) },
    korrespondent_neu: korrespondentNeu,
    notiz: `KI-Prüfung (Gemini, Sicherheit ${ki.sicherheit ?? '?'}): ${ki.pruefhinweis || ''}` +
           (aenderungen.length ? `\nGeändert: ${aenderungen.join('; ')}` : '\nKeine Feldänderung.') +
           (ki.ist_zahlungsbeleg ? '\nHinweis: Zahlungsbeleg, keine Rechnung.' : '') +
           `\nVorher: ${JSON.stringify(vorher)}`,
  }});
}
return out;

// neu angelegten Korrespondenten in den PATCH übernehmen
const src = $('Änderungen + Tag bauen').item.json;
return { json: { ...src, patch: { ...src.patch, correspondent: $json.id } } };
